.pbr_stepper__title:before {
    position: absolute;
    content: "";
    display: block;
    top: -60px;
    right: 0;
    bottom: -99px;
    left: 0;
    background-image: -webkit-gradient(linear, left top, left bottom, from(#2cbae6), to(#009eca));
    background-image: -o-linear-gradient(#2cbae6, #009eca);
    background-image: linear-gradient(#2cbae6, #009eca);
    z-index: -1
}

.pbr_stepper ul.stepper.horizontal .step:before {
    display: none
}

.pbr_stepper ul.stepper.horizontal .step:after {
    display: none
}

.pbr_stepper ul.stepper.horizontal .step:not(:last-of-type) .step-progress:after {
    background-color: #b5e7f6;
    content: "";
    display: block;
    width: 100%;
    height: 3px;
    -webkit-transform: translate(50%, 15px);
    transform: translate(50%, 15px)
}

