    background: none
}

.pbr_stepper ul.stepper.horizontal .step-title:before {
    background-color: #b5e7f6;
    color: #2cbae6;
    position: absolute;
    counter-increment: section;
    content: counter(section);
    height: 28px;
    width: 28px;
    border-radius: 50%;
    text-align: center;
    line-height: 28px;
    font-weight: 500;
    font-size: 15px;
    top: 0;
    left: 50%;
    -webkit-transform: translateX(-50%);
    transform: translate(-50%)
}

.pbr_stepper ul.stepper.horizontal .step.active .step-progress:after {
    background-image: -webkit-gradient(linear, left top, right top, from(#fff), to(#b5e7f6));
    background-image: -o-linear-gradient(left, #fff, #b5e7f6);
    background-image: linear-gradient(to right, #fff, #b5e7f6)
}

.pbr_stepper ul.stepper.horizontal .step.active .step-title:before {
    background-color: #fff
}

.pbr_stepper ul.stepper.horizontal .step.active:after {
    display: none
}

.pbr_stepper ul.stepper.horizontal .step.done .step-progress:after {
