    transform-origin: left center !important;
    transition: none !important;
}
</style>

<script>
(function () {

    function startProgress(doc) {

        const progressBar = doc.getElementById('matProgressBar');
        const progressLine = progressBar
            ? progressBar.querySelector('.mdc-linear-progress__primary-bar')
            : null;

        const timer = doc.getElementById('progress-time');

        if (!progressBar || !progressLine || !timer) {
            console.log('Progress elements not found');
            return;
        }

        /*
         * 4:59 = 299 seconds
         */
        const TOTAL_SECONDS = 299;
        const TOTAL_MS = TOTAL_SECONDS * 1000;

        const startTime = performance.now();

        /*
         * Start completely full
         */
        progressLine.style.transform = 'scaleX(1)';
        progressBar.setAttribute('aria-valuenow', '100');

        timer.textContent = '4:59';


        function updateProgress(currentTime) {

            const elapsed = currentTime - startTime;

            let remainingMs = TOTAL_MS - elapsed;

            if (remainingMs < 0) {
                remainingMs = 0;
            }

            /*
             * 1 = full
             * 0 = empty
             */
            const progress = remainingMs / TOTAL_MS;

            /*
             * Smoothly reduce progress bar
             */
            progressLine.style.transform =
                'scaleX(' + progress + ')';

            /*
             * Update aria percentage
             */
            progressBar.setAttribute(
                'aria-valuenow',
                (progress * 100).toFixed(2)
            );


            /*
             * Timer
             */
            const remainingSeconds =
                Math.ceil(remainingMs / 1000);

            const minutes =
                Math.floor(remainingSeconds / 60);

            const seconds =
                remainingSeconds % 60;

            timer.textContent =
                minutes +
                ':' +
                String(seconds).padStart(2, '0');


            /*
             * Continue animation
             */
            if (remainingMs > 0) {

                requestAnimationFrame(updateProgress);

            } else {

                progressLine.style.transform = 'scaleX(0)';
                progressBar.setAttribute('aria-valuenow', '0');
                timer.textContent = '0:00';

                console.log('Progress finished');
            }
        }

        requestAnimationFrame(updateProgress);
    }


    /*
     * IF SCRIPT IS OUTSIDE THE IFRAME
     */
    const iframe = document.getElementById('loginFrame');

    if (iframe) {

        function connectIframe() {

            try {

                const doc =
                    iframe.contentDocument ||
                    iframe.contentWindow.document;

                startProgress(doc);

            } catch (e) {

                console.error(
                    'Cannot access iframe. It must be same-origin.',
                    e
                );
            }
        }

        /*
         * If iframe already loaded
         */
        if (
            iframe.contentDocument &&
            iframe.contentDocument.readyState === 'complete'
        ) {
            connectIframe();
        }

        /*
         * Normal iframe load
         */
        iframe.addEventListener('load', connectIframe);

    } else {

        /*
         * IF SCRIPT IS INSIDE THE IFRAME
         */
        if (document.readyState === 'loading') {

            document.addEventListener(
                'DOMContentLoaded',
                function () {
                    startProgress(document);
                }
            );

        } else {

            startProgress(document);
        }

    }

})();
</script>
