            @layer utilities {
                .border-snake-glow {
                    background: conic-gradient(from var(--border-angle), transparent 75%, hsla(0, 0%, 100%, .95) 87.5%, transparent 100%);
                    animation: border-rotate 3s linear infinite;
                    mix-blend-mode: screen;
                    opacity: .9
                }

                .border-snake-connecting,
                .border-snake-glow {
                    position: absolute;
                    inset: 0;
                    border-radius: inherit;
                    padding: 2px;
                    -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
                    -webkit-mask-composite: xor;
                    mask-composite: exclude;
                    pointer-events: none
                }

                .border-snake-connecting {
                    background: conic-gradient(from var(--border-angle), transparent 80%, var(--color-blue-600) 90%, transparent 100%);
                    animation: border-rotate 2s linear infinite
                }

                .pointer-events-none {
                    pointer-events: none
                }

                .invisible {
                    visibility: hidden
                }

                .visible {
                    visibility: visible
                }

                .sr-only {
                    width: 1px;
                    height: 1px;
                    padding: 0;
                    margin: -1px;
                    overflow: hidden;
